"""L1.5 - the 10 test cases generated by the AI assistant for cart and order placement.
IDs AI-TC-01..10.  Run against the prototype as committed (and against the lab-fixed copy)."""
from decimal import Decimal
from orders.models import Order, OrderItem
from .base import CartBase


class AIGenerated10(CartBase):
    def test_AI_TC_01_add_item_creates_cart_line(self):
        self.add(self.burger)
        self.assertEqual(self.qty(self.burger), 1)

    def test_AI_TC_02_adding_same_item_twice_gives_quantity_two(self):
        self.add(self.burger, 2)
        self.assertEqual(self.qty(self.burger), 2)

    def test_AI_TC_03_minus_button_reduces_quantity(self):
        self.add(self.burger, 2)
        self.client.get(f'/orders/cart/remove/{self.burger.id}/')
        self.assertEqual(self.qty(self.burger), 1)

    def test_AI_TC_04_minus_on_last_unit_removes_line(self):
        self.add(self.burger)
        self.client.get(f'/orders/cart/remove/{self.burger.id}/')
        self.assertNotIn(str(self.burger.id), self.cart())

    def test_AI_TC_05_cart_total_is_sum_of_price_times_quantity(self):
        self.add(self.burger, 2); self.add(self.fries)
        r = self.client.get('/orders/cart/')
        self.assertEqual(r.context['total_price'], Decimal('21.97'))   # 2*8.99 + 3.99

    def test_AI_TC_06_anonymous_checkout_redirects_to_login(self):
        self.add(self.burger)
        r = self.client.get('/orders/checkout/')
        self.assertEqual(r.status_code, 302)
        self.assertIn('/accounts/login/', r.url)

    def test_AI_TC_07_empty_cart_checkout_redirects_to_cart(self):
        self.login()
        r = self.client.get('/orders/checkout/')
        self.assertRedirects(r, '/orders/cart/', fetch_redirect_response=False)

    def test_AI_TC_08_valid_order_creates_items_and_clears_cart(self):
        self.login(); self.add(self.burger, 2); self.add(self.fries)
        r = self.client.post('/orders/checkout/', self.DETAILS)
        self.assertRedirects(r, '/orders/history/', fetch_redirect_response=False)
        o = Order.objects.get()
        self.assertEqual(o.items.count(), 2)
        self.assertEqual(self.cart(), {})

    def test_AI_TC_09_order_stores_delivery_details(self):
        self.login(); self.add(self.burger)
        self.client.post('/orders/checkout/', self.DETAILS)
        o = Order.objects.get()
        self.assertEqual((o.full_name, o.phone_number, o.address),
                         (self.DETAILS['full_name'], self.DETAILS['phone_number'], self.DETAILS['address']))

    def test_AI_TC_10_order_stores_total_amount(self):
        self.login(); self.add(self.burger, 2); self.add(self.fries)
        self.client.post('/orders/checkout/', self.DETAILS)
        self.assertEqual(Order.objects.get().total_amount, Decimal('21.97'))
